from django import forms

from .models import Member


class MemberForm(forms.ModelForm):
    """Add or edit a member. The member ID is generated by the system and never edited."""

    class Meta:
        model = Member
        fields = ["full_name", "email", "phone", "national_id_number", "joined_date", "is_designated_admin"]
        labels = {"is_designated_admin": "Designated administrator"}
        widgets = {"joined_date": forms.DateInput(attrs={"type": "date"}, format="%Y-%m-%d")}

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        for field in self.fields.values():
            widget = field.widget
            if isinstance(widget, forms.CheckboxInput):
                css = "form-check-input"
            else:
                css = "form-control"
            widget.attrs["class"] = f"{widget.attrs.get('class', '')} {css}".strip()
